mapper.select:
SELECT d.id, d.id_site, d.devicename, d.datatablename, d.job_tablename, d.last_updated, d.id_device_group, s.start_date_time, s.end_date_time, t.`value` AS timezone_value, e.id AS id_error, d.id AS id_device, d.id_device_type, d.serial_number, s.cf_alert_threshold, s.cf_start_time, s.cf_end_time FROM device d INNER JOIN site s ON s.id = d.id_site AND s.`status` = 1 INNER JOIN time_zone t ON t.id = s.id_time_zone LEFT JOIN error e ON e.id_device_group = d.id_device_group AND e.error_code = #{error_code} AND e.`status` = 1 AND e.is_delete = 0 WHERE d.`status` = 1 AND d.is_delete = 0 AND d.disable_alert = 1
AND d.id_device_type IN
#{item}
AND d.id_site IN
#{item}
AND d.serial_number = #{serial_number}
AND e.id IS NOT NULL GROUP BY d.id

SELECT d.time FROM ${data_table_name} d WHERE d.error = 0 
	AND d.id_device = #{id_device}
	AND time <= #{reference_time}
ORDER BY d.time DESC limit 1;

SELECT d.time FROM ${data_table_name} d WHERE d.nvmActivePower > 0 
	AND d.id_device = #{id_device}
	AND time <= #{reference_time}
ORDER BY d.time DESC limit 1;

SELECT MIN(d.time) FROM ${data_table_name} d WHERE d.error = 0
AND d.id_device = #{id_device}
AND d.time > #{reference_time}
ORDER BY d.time ASC limit 1;
